Here is the root cause:
When `DRM_BUDDY_CONTIGUOUS_ALLOCATION` is set, the requested size is rounded up to the next power-of-two via `roundup_pow_of_two()`, and for non-contiguous allocations with a large `min_block_size`, the size is aligned via `round_up()`. Both operations can produce a rounded size that exceeds the total memory manager size (`mm->size`), causing the calculated order to exceed `mm->max_order`, which later triggers `BUG_ON(order > mm->max_order)` in the allocation loop. The bug occurs because there is no validation of the rounded size against `mm->size` before the BUG_ON.

Here is the patch:
  */
 int drm_buddy_alloc_blocks(struct drm_buddy *mm,
 			   u64 start, u64 end, u64 size,
 			   u64 min_block_size,
 			   struct list_head *blocks,
 			   unsigned long flags)
 {
 	struct drm_buddy_block *block = NULL;
 	u64 original_size, original_min_size;
 	unsigned int min_order, order;
 	LIST_HEAD(allocated);
 	unsigned long pages;
 	int err;

 	if (size < mm->chunk_size)
 		return -EINVAL;

 	if (min_block_size < mm->chunk_size)
 		return -EINVAL;

 	if (!is_power_of_2(min_block_size))
 		return -EINVAL;

 	if (!IS_ALIGNED(start | end | size, mm->chunk_size))
 		return -EINVAL;

 	if (end > mm->size)
 		return -EINVAL;

 	if (range_overflows(start, size, mm->size))
 		return -EINVAL;

 	/* Actual range allocation */
 	if (start + size == end) {
 		if (!IS_ALIGNED(start | end, min_block_size))
 			return -EINVAL;

 		return __drm_buddy_alloc_range(mm, start, size, NULL, blocks);
 	}

 	original_size = size;
 	original_min_size = min_block_size;

 	/* Roundup the size to power of 2 */
 	if (flags & DRM_BUDDY_CONTIGUOUS_ALLOCATION) {
 		size = roundup_pow_of_two(size);
 		min_block_size = size;
 	/* Align size value to min_block_size */
 	} else if (!IS_ALIGNED(size, min_block_size)) {
 		size = round_up(size, min_block_size);
 	}

 	pages = size >> ilog2(mm->chunk_size);
 	order = fls(pages) - 1;
 	min_order = ilog2(min_block_size) - ilog2(mm->chunk_size);

+	if (order > mm->max_order || size > mm->size) {
+		if ((flags & DRM_BUDDY_CONTIGUOUS_ALLOCATION) &&
+		    !(flags & DRM_BUDDY_RANGE_ALLOCATION))
+			return __alloc_contig_try_harder(mm, original_size,
+							 original_min_size, blocks);
+
+		return -EINVAL;
+	}
+
 	do {
 		order = min(order, (unsigned int)fls(pages) - 1);
 		BUG_ON(order > mm->max_order);
 		BUG_ON(order < min_order);

 		do {
 			block = __drm_buddy_alloc_blocks(mm, start,
 							 end,
 							 order,
 							 flags);
 			if (!IS_ERR(block))
 				break;

 			if (order-- == min_order) {
 				/* Try allocation through force merge method */
 				if (mm->clear_avail &&
 				    !__force_merge(mm, start, end, min_order)) {
 					block = __drm_buddy_alloc_blocks(mm, start,
 									 end,
 									 min_order,
 									 flags);
 					if (!IS_ERR(block)) {
 						order = min_order;
 						break;
 					}
 				}

 				/*
 				 * Try contiguous block allocation through
 				 * try harder method.
 				 */
 				if (flags & DRM_BUDDY_CONTIGUOUS_ALLOCATION &&
 				    !(flags & DRM_BUDDY_RANGE_ALLOCATION))
 					return __alloc_contig_try_harder(mm,
 									 original_size,
 									 original_min_size,
 									 blocks);
 				err = -ENOSPC;
 				goto err_free;
 			}
 		} while (1);

 		mark_allocated(mm, block);
 		mm->avail -= drm_buddy_block_size(mm, block);
 		if (drm_buddy_block_is_clear(block))
 			mm->clear_avail -= drm_buddy_block_size(mm, block);
 		kmemleak_update_trace(block);
 		list_add_tail(&block->link, &allocated);

 		pages -= BIT(order);

 		if (!pages)
 			break;
 	} while (1);

 	/* Trim the allocated block to the required size */
 	if (!(flags & DRM_BUDDY_TRIM_DISABLE) &&
 	    original_size != size) {
 		struct list_head *trim_list;
 		LIST_HEAD(temp);
 		u64 trim_size;

 		trim_list = &allocated;
 		trim_size = original_size;

 		if (!list_is_singular(&allocated)) {
 			block = list_last_entry(&allocated, typeof(*block), link);
 			list_move(&block->link, &temp);
 			trim_list = &temp;
 			trim_size = drm_buddy_block_size(mm, block) -
 				(size - original_size);
 		}

 		drm_buddy_block_trim(mm,
 				     NULL,
 				     trim_size,
 				     trim_list);

 		if (!list_empty(&temp))
 			list_splice_tail(trim_list, &allocated);
 	}

 	list_splice_tail(&allocated, blocks);
 	return 0;

 err_free:
 	drm_buddy_free_list_internal(mm, &allocated);
 	return err;
 }
 EXPORT_SYMBOL(drm_buddy_alloc_blocks);


